async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  let validator = tool.compiledValidator;

  if (!validator) {
    const schema = definition.inputSchema;
    if (this.functionValidatorCache.has(schema)) {
      validator = this.functionValidatorCache.get(schema)!;
    } else {
      validator = ajvInstance.compile(schema);
      this.functionValidatorCache.set(schema, validator);
    }
  }

  const isValid = validator(input);
  if (!isValid && validator.errors) {
    const errorMessages = validator.errors.map(err => {
      const path = err.instancePath || '/';
      const fieldName = path.startsWith('/') ? path.slice(1) : path;
      if (err.keyword === 'required') {
        return `Missing required field: ${err.params.missingProperty}`;
      }
      if (err.keyword === 'type') {
        return `Field '${fieldName}' must be of type ${err.params.type}`;
      }
      return `Validation failed at ${fieldName}: ${err.message}`;
    });
    const resultMessage = errorMessages.join('; ');
    log.info('tool', 'schema validation failed', {name, validationError: resultMessage});
    return {result: resultMessage};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
}

